WITH base AS (SELECT id, product_name, category, price, cost, stock_qty, launch_date, tags, supplier_id, GREATEST(stock_qty, price) greatest_stock_qty_price, YEAR(launch_date) launch_date_year, COALESCE(brand, 'N/A') resolved_brand FROM products WHERE launch_date > DATE '2024-02-24' AND supplier_id IS NOT NULL) SELECT DATE_TRUNC('MONTH', launch_date) AS activity_month, COUNT_IF(category = 'Fashion') AS fashion_events, COUNT_IF(category = 'Fashion') AS fashion_events_2, APPROX_PERCENTILE(launch_date_year, 0.5) AS launch_date_year_p50 FROM base GROUP BY 1
